import json
n=30
g=[[0]*n for _ in range(n)]
# Preserve the given outer 5-frame.
for c in range(1,26):
    g[1][c]=g[25][c]=5
for r in range(1,26):
    g[r][1]=g[r][25]=5
# Demo pattern: fill the area inside the outer frame but outside an inset-2 square with 2.
for r in range(2,25):
    for c in range(2,25):
        if r < 3 or r > 23 or c < 3 or c > 23:
            g[r][c]=2
# Draw the inset square outline in 5; leave its center at 0.
for c in range(3,24):
    g[3][c]=g[23][c]=5
for r in range(3,24):
    g[r][3]=g[r][23]=5
assert len(g)==30 and all(len(row)==30 for row in g)
assert set(sum(g,[])) <= {0,2,5}
print(json.dumps(g,separators=(',',':')))

